    "create_time" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "update_time" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "tenant_id" BIGINT NOT NULL,
    "status" SMALLINT DEFAULT 1,
    "del_flag" SMALLINT DEFAULT 0,
    "create_by" CHARACTER VARYING(64),
    "update_by" CHARACTER VARYING(64),
    CONSTRAINT "pk_edu_learning_state" PRIMARY KEY("id"),
    CONSTRAINT "uk_learning_state_tenant" UNIQUE  ("tenant_id", "student_id", "knowledge_id")
);

CREATE TABLE "edu_achievement"(
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1)  NOT NULL,
    "student_id" BIGINT NOT NULL,
    "code" CHARACTER VARYING(50) NOT NULL,
    "name" CHARACTER VARYING(100) NOT NULL,
    "description" CHARACTER VARYING(500) DEFAULT NULL,
    "icon" CHARACTER VARYING(200) DEFAULT NULL,
    "earned_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "tenant_id" BIGINT NOT NULL,
    "status" SMALLINT DEFAULT 1,
    "del_flag" SMALLINT DEFAULT 0,
    "create_by" CHARACTER VARYING(64),
    "create_time" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "update_by" CHARACTER VARYING(64),
    "update_time" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_edu_achievement" PRIMARY KEY("id"),
    CONSTRAINT "uk_achievement_tenant" UNIQUE  ("tenant_id", "student_id", "code")
);

