-- PostgreSQL triggers corresponding to H2 ON UPDATE CURRENT_TIMESTAMP.
CREATE FUNCTION shiyu_touch_edu_student_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW."updated_at" = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER shiyu_touch_edu_student_updated_at BEFORE UPDATE ON "edu_student"
FOR EACH ROW EXECUTE FUNCTION shiyu_touch_edu_student_updated_at();

